-- TODO: port this table and upsert to PostgreSQL, then note the MySQL and SQLite versions.
CREATE TABLE players (
    id INTEGER AUTO_INCREMENT PRIMARY KEY,
    handle VARCHAR(64) NOT NULL UNIQUE,
    email VARCHAR(255) NOT NULL,
    active TINYINT(1) NOT NULL DEFAULT 1
);

INSERT INTO players (handle, email, active)
VALUES ('ada', 'ada@example.com', 1)
ON DUPLICATE KEY UPDATE email = 'ada@example.com';

SELECT * FROM players WHERE handle = 'ada' LIMIT 1;
